_MAX_SESSION_BYTES = 50 * 1024

_THINK_OPEN = "<think>"
_THINK_CLOSE = "</think>"


def _partial_tag_suffix(text: str, tag: str) -> str:
    """Return the longest suffix of ``text`` that is a proper prefix of ``tag``.

    Used to hold back a partial ``<think>``/``</think>`` tag that is split across
    streaming chunks so it can be re-parsed once the next chunk arrives.
    """
    max_len = min(len(text), len(tag) - 1)
    for length in range(max_len, 0, -1):
        if text[-length:] == tag[:length]:
            return text[-length:]
    return ""


def _strip_think_blocks(buf: str, in_think: bool) -> tuple[str, str, bool]:
    """Strip ``<think>...</think>`` spans from a streaming text buffer.

    Returns a 3-tuple ``(emit_text, remaining_buf, new_in_think_flag)`` where
    ``emit_text`` is safe to show users, ``remaining_buf`` holds any partial
    open/close tag that must be re-fed with the next chunk, and
    ``new_in_think_flag`` indicates whether the parser is inside a think block.
    """
    emit: list[str] = []
    while True:
        if in_think:
            idx = buf.find(_THINK_CLOSE)
            if idx == -1:
                # No closing tag yet; drop the reasoning text but keep any
                # partial closing tag at the end for the next chunk.
                partial = _partial_tag_suffix(buf, _THINK_CLOSE)
                return "".join(emit), partial, True
            buf = buf[idx + len(_THINK_CLOSE) :]
            in_think = False
        else:
            idx = buf.find(_THINK_OPEN)
            if idx == -1:
                # No opening tag; emit everything except a trailing partial tag.
                partial = _partial_tag_suffix(buf, _THINK_OPEN)
                emit.append(buf[: len(buf) - len(partial)] if partial else buf)
                return "".join(emit), partial, False
            emit.append(buf[:idx])
            buf = buf[idx + len(_THINK_OPEN) :]
