def _merge_tool_call_chunk(acc: list[dict[str, Any]], chunk: dict[str, Any]) -> None:
    """Merge a streaming ``tool_calls`` delta ``chunk`` into ``acc`` in place.

    The first chunk seen for a given ``index`` seeds the ``id`` and function
    ``name``; every chunk concatenates its ``function.arguments`` fragment so the
    full argument string is reconstructed. Parallel tool calls at distinct
    indexes are tracked independently.
    """
    index = chunk.get("index", 0)
    entry = next((e for e in acc if e.get("index") == index), None)
    fn = chunk.get("function") or {}
    if entry is None:
        entry = {
            "index": index,
            "id": chunk.get("id"),
            "type": chunk.get("type", "function"),
            "function": {"name": fn.get("name"), "arguments": ""},
        }
        acc.append(entry)
    if fn.get("arguments"):
        entry["function"]["arguments"] += fn["arguments"]


def _trim_session(messages: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Drop the oldest non-system messages until the history fits the byte cap.

    The system message at index 0 is always preserved and the most recent
    messages are retained.
    """
    while len(messages) > 2 and len(json.dumps(messages).encode()) > _MAX_SESSION_BYTES:
        messages.pop(1)
    return messages


